DECLARE @Name_71f1a04e4ed0 NVARCHAR(255),
@CategoryID_71f1a04e4ed0 UNIQUEIDENTIFIER,
@UserQuestion_71f1a04e4ed0 NVARCHAR(MAX),
@Description_71f1a04e4ed0 NVARCHAR(MAX),
@SQL_71f1a04e4ed0 NVARCHAR(MAX),
@TechnicalDescription_71f1a04e4ed0 NVARCHAR(MAX),
@OriginalSQL_71f1a04e4ed0 NVARCHAR(MAX),
@Feedback_71f1a04e4ed0 NVARCHAR(MAX),
